				if (typeof item === "string") return item;
				if (item && typeof item === "object" && typeof (item as { text?: unknown }).text === "string") {
					return (item as { text: string }).text;
				}
				return "";
			})
			.filter(Boolean)
			.join(" ")
			.trim();
	}
	return "";
